xml_node_t * rb_xml_reader_attribute_hash(const xml_node_t *node) { xml_node_t *ret = (xml_node_t *) rb_hash_new2_node(ret); rb_xml_tree_t *t = (xml_node_t *) node; if (!has_attributes(t)) return ret; while (t) { const xml_text_reader_t *txt = xmlTextReaderExpand(t); rb_node_t *n = txt->first; while (n) { const char *name = nokogiri_str_new2_stub(n->name); char *val = NULL; xml_node_t *stub = xmlNodeGetContent(n); if (stub) { val = nokogiri_str_new2_stub(stub); free(stub); } rb_hash_aset(ret, name, val); n = n->next; } } return ret; }